def priority(item: float, bins: np.ndarray) -> np.ndarray:
    target = 0.5
    fill_after = bins + item
    return -np.abs(fill_after - target)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    ideal_fill = item
    fill_after = bins + item
    diff = fill_after - ideal_fill
    return np.exp(-(diff ** 2))
